struct Node;

/// 9999-12-31T23:59:59Z, the last instant whose date renders as a 10-character YYYY-MM-DD.
const MAX_SECS: u64 = 253_402_300_799;

/// Converts days since 1970-01-01 to (year, month, day) in the proleptic Gregorian calendar.
/// Howard Hinnant's civil_from_days algorithm.
fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = yoe + era * 400 + (if m <= 2 { 1 } else { 0 });
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wasi::clocks::wall_clock::now();
        let secs = now.seconds;

        // Clamp only the date computation so the rendered date is always 10 characters.
        let clamped = secs.min(MAX_SECS);
        let days = (clamped / 86_400) as i64;
        let (y, m, d) = civil_from_days(days);

        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started: secs,
        }
    }
}

export!(Node);
```

I did not add the enrichment fetch. The node's `with` clause grants only `wasi:clocks/wall-clock@0.2.0`, so an HTTP import would reach outside the authority this node was given. The fetch URL also carries the raw `tick.reason` text to an external host, which is a data-exposure concern. If you want that enrichment, it needs to be granted explicitly to this node, and the URL should encode the query.

